def normalize(s):
    s=unicodedata.normalize('NFC',s).lower().strip()
    s=re.sub(r'^(at|en|et)\s+','',s)
    return re.sub(r'\s+',' ',re.sub(r'[.,!?]','',s)).strip()


def read_rows(path):
    if path.suffix.lower()=='.json':
        sheets=json.loads(path.read_text())
        return {int(re.sub(r'\D','',r[0]['cell'])):{re.sub(r'\d','',c['cell']):c['value'] for c in r} for r in sheets[0]['rows']}
    ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    with zipfile.ZipFile(path) as z:
        shared=[]
        if 'xl/sharedStrings.xml' in z.namelist():
            shared=[''.join(e.itertext()) for e in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('s:si',ns)]
        sheet=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
        rows={}
        for row in sheet.findall('.//s:sheetData/s:row',ns):
            values={}
            for c in row.findall('s:c',ns):
                v=c.find('s:v',ns)
                text=v.text or '' if v is not None else ''
                if c.attrib.get('t')=='s': text=shared[int(text)]
                if c.attrib.get('t')=='inlineStr': text=''.join(c.find('s:is',ns).itertext())
                values[re.sub(r'\d','',c.attrib['r'])]=text
            if values and any(v.strip() for v in values.values()): rows[int(row.attrib['r'])]=values
        return rows


def baseline():
    script="""import {enrichedVocabulary as v} from './dist/vocabulary-enrichment.mjs';
import {courseItems as c} from './dist/course.mjs';
console.log(JSON.stringify([...v,...c].flatMap(x=>[x.da,...(x.daAnswers||[])])));"""
    out=subprocess.check_output(['node','--input-type=module','-e',script],cwd=ROOT,text=True)
    return set(map(normalize,json.loads(out)))


def rebuild(paths):
    old=baseline(); seen=set(old); cards=[]; review=[]; summaries=[]; audit=[]
    known=old | {normalize(line.split('|')[1]) for table in (REVIEWED_FIRST,REVIEWED_SECOND) for line in table.strip().splitlines() if line.strip()}
    for doc,(path,table,aliases) in enumerate(zip(paths,[REVIEWED_FIRST,REVIEWED_SECOND],[ALIASES_FIRST,ALIASES_SECOND])):
        rows=read_rows(path); dc,rc=('A','C') if doc==0 else ('B','A')
        byrow={}; added=set(); duplicate=set(); classified=set()
        for line in table.strip().splitlines():
            if not line.strip(): continue
            fields=line.split('|'); assert len(fields) in (6,7), line
            row=int(fields[0]); da,ru,exd,exr,association=fields[1:6]; note=fields[6] if len(fields)==7 else ''
            byrow.setdefault(row,[]).append(da)
            key=normalize(da)
            if key in seen: duplicate.add(row); continue
            assert not re.search(r'[А-Яа-яЁё]',da),da
            source=rows[row]; original=f'{dc}{row}: {source.get(dc,"")} | {rc}{row}: {source.get(rc,"")}'
            card={'id':'doc-'+hashlib.sha256((SOURCES[doc]+'\0'+str(row)+'\0'+key).encode()).hexdigest()[:12], 'da':da,'ru':ru,'exampleDa':exd,'exampleRu':exr,'association':association,'verified':True,'sourceDocument':SOURCES[doc],'sourceRow':row,'original':original}
            if note: card['note']=note
            if da=='tage afsted': card['daAnswers']=['tage afsted','tage af sted']
            if da=='svært': card['daAnswers']=['svært','vanskeligt']
            if da=='Det er ikke rigtigt.': card['daAnswers']=['Det er ikke rigtigt.','Dette er ikke rigtigt.']
            cards.append(card); seen.add(key); added.add(row)
        stat={'sourceDocument':SOURCES[doc],'dataRows':len(rows)-1,'addedRows':0,'duplicateRows':0,'needsReviewRows':0,'excludedRows':0,'importedEntries':sum(c['sourceDocument']==SOURCES[doc] for c in cards)}
        for row,source in rows.items():
            if row==1: continue
            if row in added: status='added'
            elif row in REVIEW[doc]:
                status='needsReview'; reason=REVIEW[doc][row]
                medical=row in (288,346) and doc==0
                original='[Медицинская пометка исключена из тренировочного материала.]' if medical else f'{dc}{row}: {source.get(dc,"")} | {rc}{row}: {source.get(rc,"")}'
                review.append({'id':f'doc-review-{doc+1}-{row}','sourceDocument':SOURCES[doc],'sourceRow':row,'original':original,'reason':reason,'verified':False})
            elif row in EXCLUDED[doc]: status='excluded'
            elif row in duplicate or normalize(source.get(dc,'')) in known: status='duplicate'
            elif row in aliases and all(normalize(s) in known for s in aliases[row]): status='duplicate'
            else: raise ValueError(f'Unreviewed source row: {SOURCES[doc]} {row}: {source}')
            stat[status+'Rows' if status!='needsReview' else 'needsReviewRows']+=1
            audit.append({'sourceDocument':SOURCES[doc],'sourceRow':row,'status':status,**({'reason':EXCLUDED[doc][row]} if status=='excluded' else {})})
        summaries.append(stat)
    summary={'sourceRows':sum(s['dataRows'] for s in summaries),'importedEntries':len(cards),'needsReviewRows':len(review),'duplicateRows':sum(s['duplicateRows'] for s in summaries),'excludedRows':sum(s['excludedRows'] for s in summaries),'documents':summaries}
    target=ROOT/'dist/document-vocabulary.mjs'
    target.write_text('// Generated by tools/import-document-vocabulary.py; original XLSX sources are read-only.\n// Original transcription columns are deliberately omitted; Danish text is used for TTS.\n'+ '\n\n'.join('export const '+name+' = '+json.dumps(value,ensure_ascii=False,indent=2)+';' for name,value in [('documentVocabulary',cards),('documentNeedsReview',review),('documentImportSummary',summary),('documentSourceAudit',audit)])+'\n')
    print(json.dumps(summary,ensure_ascii=False,indent=2))


if __name__=='__main__':
    if len(sys.argv)!=3: raise SystemExit(__doc__)
    rebuild([Path(p) for p in sys.argv[1:]])
